const p = JSON.parse($input.first().json.input || '{}');
const admins = ($env.SAVIA_ADMIN_PHONES || '').split(',').map(s => { const n = s.trim(); return n.startsWith('+') ? n.slice(1) : n; }).filter(Boolean);
if (!admins.length) return [{ json: { ok: false, error: 'SAVIA_ADMIN_PHONES no configurado' } }];
const msg = '🔔 SAVIA — Escalar a humano\nMotivo: ' + (p.motivo || 'otro') + '\nCliente: ' + (p.telefono || 'desconocido') + '\nResumen: ' + (p.resumen || '');
for (const phone of admins) {
  await $helpers.httpRequest({
    method: 'POST',
    url: $env.EVOLUTION_API_URL + '/message/sendText/' + $env.EVOLUTION_INSTANCE_SAVIA,
    headers: { apikey: $env.EVOLUTION_API_KEY, 'Content-Type': 'application/json' },
    body: { number: phone, text: msg }
  });
}
return [{ json: { ok: true, escalado: true } }];

